#!/usr/bin/env python3
"""Aplica consenso conservador y filtra asociaciones sin tocar el plan original."""
from __future__ import annotations
import argparse,hashlib,json
from pathlib import Path
def digest(path):return hashlib.sha256(path.read_bytes()).hexdigest()
def main():
 p=argparse.ArgumentParser();p.add_argument("--policy",type=Path,required=True);p.add_argument("--review",type=Path,required=True);p.add_argument("--vlm",type=Path,required=True);p.add_argument("--plan",type=Path,required=True);p.add_argument("--output-gate",type=Path,required=True);p.add_argument("--output-plan",type=Path,required=True);a=p.parse_args();policy=json.loads(a.policy.read_text());review=json.loads(a.review.read_text());vlm=json.loads(a.vlm.read_text());plan=json.loads(a.plan.read_text())
 if policy.get("status")!="frozen_experimental_authorized" or policy.get("human_review_replaced") is not False:raise ValueError("política automática no autorizada")
 metrics={(r["query_id"],r["reference_image_id"],r["candidate_image_id"]):r for r in review["pairs"]};verdicts={(r["query_id"],r["reference_image_id"],r["candidate_image_id"]):r for r in vlm["records"]};decisions=[]
 for key,row in metrics.items():
  v=verdicts[key];clip=row["ai_metrics"]["clip_l14_336_cosine"];color=row["ai_metrics"]["rgb_histogram_cosine"];retain=v["verdict"]=="different_scene" and v["facade_match"]=="no" and v["geometry_match"]=="no" and v["distinctive_elements_match"]=="no" and not row["exact_duplicate"] and row["dhash_distance"]>12 and not(clip>=.96 and color>=.97);reason="retained_consensus_different_scene" if retain else "excluded_conservative_"+v["verdict"];decisions.append({"query_id":key[0],"reference_image_id":key[1],"candidate_image_id":key[2],"decision":"retain" if retain else "exclude","reason":reason,"signals":{"vlm_verdict":v["verdict"],"viewpoint_relation":v["viewpoint_relation"],"facade_match":v["facade_match"],"geometry_match":v["geometry_match"],"distinctive_elements_match":v["distinctive_elements_match"],"clip_cosine":clip,"rgb_histogram_cosine":color,"dhash_distance":row["dhash_distance"],"exact_duplicate":row["exact_duplicate"]},"reviewer_kind":"automated","reviewer":"automated_conservative_overlap_gate_v1","human_review":False})
 retained={(r["query_id"],r["candidate_image_id"]) for r in decisions if r["decision"]=="retain"};associations=[r for r in plan["associations"] if (r["query_id"],r["image_id"]) in retained];claims={q["query_id"]:q["claims"] for q in plan["queries"]};logical=sum(len(claims[r["query_id"]]) for r in associations);abstain=sum(sum(c["requires_orientation"] and not r["orientation_comparable"] for c in claims[r["query_id"]]) for r in associations);slots={(r["query_id"],r["candidate_id"]) for r in associations};assets=sorted({r["image_id"] for r in associations});filtered={**plan,"contract_version":"h26-h37-candidate-visual-plan-automated-gate-v1","source_plan_id":plan["plan_id"],"plan_id":"","automated_overlap_policy_id":policy["policy_id"],"associations":associations,"asset_ids":assets,"summary":{**plan["summary"],"covered_slots":len(slots),"zero_coverage_slots":plan["summary"]["candidate_slots"]-len(slots),"logical_tasks_per_model":logical,"automatic_abstentions_per_model":abstain,"generate_calls_per_model":logical-abstain,"unique_assets":len(assets)}};filtered["plan_id"]="h26-h37-automated-gate-plan-sha256-"+hashlib.sha256(json.dumps({k:v for k,v in filtered.items() if k!="plan_id"},ensure_ascii=False,sort_keys=True,separators=(",",":")).encode()).hexdigest();gate={"schema_version":"1.0","contract_version":"automated-conservative-overlap-gate-report-v1","policy":policy,"inputs":{"review_sha256":digest(a.review),"vlm_sha256":digest(a.vlm),"source_plan_sha256":digest(a.plan)},"summary":{"pairs":len(decisions),"retained":sum(r["decision"]=="retain" for r in decisions),"excluded":sum(r["decision"]=="exclude" for r in decisions),"same_scene_excluded":sum(r["signals"]["vlm_verdict"]=="same_scene" for r in decisions),"uncertain_excluded":sum(r["signals"]["vlm_verdict"]=="uncertain" for r in decisions),"different_but_no_consensus_excluded":sum(r["signals"]["vlm_verdict"]=="different_scene" and r["decision"]=="exclude" for r in decisions),"human_approvals":0},"coverage_after_gate":filtered["summary"],"decisions":decisions,"limitations":["not_human_review","conservative_exclusion","paired_vlm_errors_possible"]};a.output_gate.write_text(json.dumps(gate,ensure_ascii=False,sort_keys=True,indent=2)+"\n");a.output_plan.write_text(json.dumps(filtered,ensure_ascii=False,sort_keys=True,indent=2)+"\n");print(json.dumps({"gate":gate["summary"],"coverage":filtered["summary"],"filtered_plan_id":filtered["plan_id"]},sort_keys=True));return 0
if __name__=="__main__":raise SystemExit(main())
